function updateBandUI(){root.querySelectorAll('.ax-eq-band').forEach(el=>el.classList.toggle('active',Number(el.querySelector('input').dataset.index)===s.eqBand));const out=root.querySelector('#ax-selected-band');if(out)out.textContent=bands[s.eqBand]+' Hz / '+(s.eq[s.eqBand]>0?'+':'')+s.eq[s.eqBand]+' dB';}
root.addEventListener('input',e=>{const t=e.target,key=t.dataset.key;if(!key)return;if(key==='illumination'||key==='typeface')return;const value=t.type==='range'?Number(t.value):t.value;if(key==='eqGain'){s.eqBand=Number(t.dataset.index);s.eq[s.eqBand]=value;s.eqPreset='CUSTOM';root.querySelector('#ax-gain-'+s.eqBand).textContent=(value>0?'+':'')+value;const p=root.querySelector('[data-key="eqPreset"]');if(p)p.value='CUSTOM';updateBandUI();}else if(key==='tuneFrequency'){s[s.band.startsWith('AM')?'am':'fm']=value;}else if(/^delay\d$/.test(key)){s.delays[Number(key.slice(-1))]=value;}else{s[key]=value;if(key==='balance'||key==='fader'){const p=root.querySelector('.ax-soundfield .point');if(p){p.style.left=(50+s.balance*3.5)+'%';p.style.top=(50+s.fader*3.5)+'%';}}if(['dayLevel','nightLevel','manualLevel'].includes(key))updateDim();if(key==='labReserve'){updateMemoryModel();}}const out=root.querySelector('#ax-out-'+key);if(out)out.textContent=value+(t.dataset.unit||'');});
root.addEventListener('change',e=>{const t=e.target,key=t.dataset.key;if(!key)return;if(key==='illumination'){changeIllumination(t.value);return;}if(key==='typeface'){changeTypeface(t.value);return;}if(['nightStart','nightEnd'].includes(key))s[key]=Number(t.value);if(key==='eqPreset')setEqPreset(t.value);if(key==='seat')s.delays=t.value==='FRONT LEFT'?[0,1.8,1.2,2.4]:t.value==='FRONT RIGHT'?[1.8,0,2.4,1.2]:t.value==='REAR LEFT'?[1.2,2.4,0,1.8]:t.value==='REAR RIGHT'?[2.4,1.2,1.8,0]:[0,0,0,0];render();save();});
root.addEventListener('focusin',e=>{const t=e.target;if(t.dataset.key==='eqGain'){s.eqBand=Number(t.dataset.index);updateBandUI();}});
root.addEventListener('pointerdown',e=>{const home=e.target.closest('[data-action="home-key"]');if(home){homeHeld=false;powerTimer=setTimeout(()=>{homeHeld=true;s.standby=true;s.playing=false;render();save();},700);return;}const t=e.target.closest('[data-action="preset"]');if(!t)return;held=false;presetTimer=setTimeout(()=>{held=true;s.store=true;preset(Number(t.dataset.index));render();save();},650);});
['pointerup','pointercancel','pointerleave'].forEach(n=>root.addEventListener(n,()=>{clearTimeout(presetTimer);clearTimeout(powerTimer);}));
root.querySelector('.mx-knob').addEventListener('wheel',e=>{e.preventDefault();s.volume=Math.max(0,Math.min(40,s.volume+(e.deltaY<0?1:-1)));s.muted=false;root.querySelector('#mx-volume-readout').textContent=String(s.volume).padStart(2,'0');save();},{passive:false});
root.querySelector('.mx-knob').addEventListener('keydown',e=>{if(['ArrowUp','ArrowRight','ArrowDown','ArrowLeft'].includes(e.key)){e.preventDefault();s.volume=Math.max(0,Math.min(40,s.volume+(['ArrowUp','ArrowRight'].includes(e.key)?1:-1)));s.muted=false;render();save();}});
